    id: 'modo-de-fazer-viola-de-cocho-mato-grosso-do-sul',
    name: { pt: 'Modo de Fazer Viola de Cocho', en: 'Crafting of the Viola de Cocho', es: 'Modo de Hacer la Viola de Cocho' },
